import{levelForScore,watcherCount,timingForLevel,createWatcher,advanceWatcher,isCaught}from'./core.mjs';
const $=id=>document.getElementById(id),scoreEl=$('score'),bestEl=$('best'),levelEl=$('level'),statusEl=$('status'),countEl=$('watcher-count'),watchersEl=$('watchers'),cat=$('cat'),scratchBtn=$('scratch'),overlay=$('overlay'),startBtn=$('start'),caughtSign=$('caught-sign'),progress=$('progress'),scratches=$('scratches');let running=false,score=0,level=1,watchers=[createWatcher(0,1,performance.now())],frame=0,scratchUntil=0,lastLevel=1;const bestKey='itchy-business.best';let best=Number(localStorage.getItem(bestKey)||0);bestEl.textContent=String(best).padStart(3,'0');
function reset(){score=0;level=1;lastLevel=1;running=true;caughtSign.hidden=true;overlay.hidden=true;scratchBtn.disabled=false;scratchBtn.textContent='TAP TO SCRATCH';watchers=[createWatcher(0,level,performance.now())];render();cancelAnimationFrame(frame);frame=requestAnimationFrame(tick)}
function syncWatchers(now){const needed=watcherCount(level);while(watchers.length<needed)watchers.push(createWatcher(watchers.length,level,now));watchers=watchers.slice(0,needed).map(w=>advanceWatcher(w,level,now))}
function tick(now){if(!running)return;syncWatchers(now);if(isCaught(watchers,now<scratchUntil)){gameOver();return}render();frame=requestAnimationFrame(tick)}
function render(){scoreEl.textContent=String(score).padStart(3,'0');levelEl.textContent=String(level).padStart(2,'0');progress.style.width=`${score%20/20*100}%`;countEl.textContent=`${watchers.length} OWNER${watchers.length===1?'':'S'}`;watchersEl.innerHTML=watchers.map((w,i)=>`<div class="window ${w.phase}"><div class="owner owner-${i}"><i class="hair"></i><span class="eyes">${w.phase==='watching'?'● ●':'› ›'}</span><b>${['MOM','DAD','KID'][i]}</b></div><small>${w.phase==='away'?'BACK TURNED':w.phase==='warning'?'TURNING!':'WATCHING'}</small></div>`).join('');const watching=watchers.some(w=>w.phase==='watching'),warning=watchers.some(w=>w.phase==='warning');document.body.classList.toggle('danger',watching);document.body.classList.toggle('warning',!watching&&warning);$('status-dot').className=watching?'red':warning?'yellow':'';statusEl.textContent=watching?'FREEZE! THEY ARE WATCHING':warning?'UH-OH… SOMEONE IS TURNING':'SAFE — SCRATCH NOW!';cat.classList.toggle('scratching',performance.now()<scratchUntil)}
function scratch(){if(!running)return;const now=performance.now();syncWatchers(now);scratchUntil=now+180;if(isCaught(watchers,true)){render();gameOver();return}score++;level=levelForScore(score);cat.classList.remove('scratching');void cat.offsetWidth;cat.classList.add('scratching');const mark=document.createElement('i');mark.textContent='✦';mark.style.left=`${42+Math.random()*16}%`;mark.style.top=`${52+Math.random()*14}%`;scratches.append(mark);setTimeout(()=>mark.remove(),500);if(level>lastLevel){lastLevel=level;statusEl.textContent=`LEVEL ${level} — MORE EYES INCOMING!`;document.body.classList.add('levelup');setTimeout(()=>document.body.classList.remove('levelup'),700)}render()}
function gameOver(){running=false;cancelAnimationFrame(frame);scratchBtn.disabled=true;caughtSign.hidden=false;cat.classList.add('busted');best=Math.max(best,score);localStorage.setItem(bestKey,String(best));bestEl.textContent=String(best).padStart(3,'0');setTimeout(()=>{overlay.hidden=false;overlay.querySelector('span').textContent='BUSTED';overlay.querySelector('h2').textContent=`You sneaked in ${score} scratch${score===1?'':'es'}.`;overlay.querySelector('p').textContent=`Reached level ${level}. Next time, freeze the instant anyone turns around.`;startBtn.textContent='TRY AGAIN'},650)}
scratchBtn.onclick=scratch;cat.onclick=scratch;startBtn.onclick=reset;addEventListener('keydown',e=>{if(e.code==='Space'){e.preventDefault();scratch()}});render();
